u1eb3ng, tr\\u1ea7m u\\u1ea5t\\r\\nC\\u00e1ch s\\u1eed d\\u1ee5ng\\r\\n- Ng\\u00e0y u\\u1ed1ng 2-4 vi\\u00ean v\\u1eabn x 2 l\\u1ea7n\\/ng\\u00e0y.\\r\\n- N\\u00ean s\\u1eed d\\u1ee5ng s\\u1ea3n ph\\u1ea9m tr\\u01b0\\u1edbc b\\u1eefa \\u0103n 30 ph\\u00fat. \\r\\n- N\\u00ean s\\u1eed d\\u1ee5ng li\\u00ean t\\u1ee5c m\\u1ed9t \\u0111\\u1ee3t t\\u1eeb 3-6 th\\u00e1ng.\\r\\n\\r\\nL\\u01b0u \\u00fd\\r\\nTh\\u1ef1c ph\\u1ea9m n\\u00e0y kh\\u00f4ng ph\\u1ea3i l\\u00e0 thu\\u1ed1c, kh\\u00f4ng c\\u00f3 t\\u00e1c d\\u1ee5ng thay th\\u1ebf thu\\u1ed1c ch\\u1eefa b\\u1ec7nh.\\r\\n\\r\\nTh\\u1eadn tr\\u1ecdng:\\r\\n\\r\\nKh\\u00f4ng d\\u00f9ng cho ng\\u01b0\\u1eddi m\\u1eabn c\\u1ea3m v\\u1edbi b\\u1ea5t k\\u1ef3 th\\u00e0nh ph\\u1ea7n n\\u00e0o\\r\\n\\r\\n \\r\\n\\r\\nTh\\u00f4ng tin s\\u1ea3n xu\\u1ea5t\\r\\nB\\u1ea3o Qu\\u1ea3n: N\\u01a1i kh\\u00f4, tho\\u00e1ng, nhi\\u1ec7t \\u0111\\u1ed9 d\\u01b0\\u1edbi 30\\u00b0C v\\u00e0 tr\\u00e1nh \\u00e1nh n\\u1eafng tr\\u1ef1c ti\\u1ebfp.\\r\\n\\r\\nN\\u01a1i s\\u1ea3n xu\\u1ea5t: Ph\\u01b0\\u1eddng M\\u1ef9 X\\u00e1, Th\\u00e0nh ph\\u1ed1 Nam \\u0110\\u1ecbnh, T\\u1ec9nh Nam \\u0110\\u1ecbnh\\r\\n\\r\\nT\\u00ean nh\\u00e0 s\\u1ea3n xu\\u1ea5t:\\r\\n\\r\\nC\\u00d4NG TY TNHH T\\u01af V\\u1ea4N Y D\\u01af\\u1ee2C QU\\u1ed0C T\\u1ebe\\r\\n\\r\\nC\\u00f4ng ty ch\\u1ecbu tr\\u00e1ch nhi\\u1ec7m v\\u1ec1 s\\u1ea3n ph\\u1ea9m:\\r\\n\\r\\nC\\u00d4NG TY TNHH T\\u01af V\\u1ea4N Y D\\u01af\\u1ee2C QU\\u1ed0C T\\u1ebe\\r\\nS\\u1ed1 9 L\\u00f4 A, Ho\\u00e0ng C\\u1ea7u, \\u0110\\u1ed1ng \\u0110a, H\\u00e0 N\\u1ed9i\\r\\n\\r\\nS\\u1ed1 gi\\u1ea5y c\\u00f4ng b\\u1ed1: 12410\\/2019\\/\\u0110KSP\",\"nha_san_xuat\":\"IMC\",\"hinh_anh_url\":\"https:\\/\\/production-cdn.pharmacity.io\\/digital\\/768x768\\/plain\\/e-com\\/images\\/ecommerce\\/P24942_1.jpg\",\"gia_ban\":210000,\"gia_niem_yet\":210000,\"don_vi_hien_thi\":\"h\\u1ed9p\",\"don_vi_tinh\":\"h\\u1ed9p\",\"selected_don_vi\":\"h\\u1ed9p\",\"so_luong_ton\":31,\"don_vi_ton\":\"h\\u1ed9p\",\"don_vi_